 metrics([['Current radius',fmt(flow.radius,4)],['Extinction time',fmt(flow.extinction,4)],['Gaussian curvature',Number.isFinite(flow.gaussian)?fmt(flow.gaussian,4):'∞'],['Surface area',fmt(flow.area,4)]]);
