function updateInverse(){posterior=G.posterior(state.radius,state.sigma,state.count,state.inverseSeed);dataset=G.generate('sphere',1200,posterior.mean);setView(dataset.points,dataset.points.map(()=>1/posterior.mean**2),0,4);$('view-title').textContent='Reconstructed sphere / posterior mean radius';$('method-badge').textContent='Bayesian grid calculation';$('legend-title').textContent='Inferred Gaussian curvature · unit⁻²';metrics([['Posterior mean radius',fmt(posterior.mean)],['95% credible interval',fmt(posterior.lo,2)+'–'+fmt(posterior.hi,2)],['Simulated true radius',fmt(state.radius,2)]]);$('experiment-note').textContent='The 3D surface shows the posterior mean radius. The distribution below shows uncertainty; the dashed line marks the simulated true radius.';drawPosterior()}
function drawPosterior(){if(!posterior)return;const svg=$('posterior-chart'),w=Math.max(280,svg.clientWidth),h=200,l=48,r=16,top=18,bottom=38,mx=Math.max(...posterior.ys);const x=v=>l+(v-.4)/2.1*(w-l-r),y=v=>h-bottom-v/mx*(h-top-bottom),points=posterior.xs.map((v,i)=>`${x(v)},${y(posterior.ys[i])}`).join(' ');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<rect x="${x(posterior.lo)}" y="${top}" width="${x(posterior.hi)-x(posterior.lo)}" height="${h-top-bottom}" fill="var(--accent)" opacity=".12"/><line x1="${l}" y1="${h-bottom}" x2="${w-r}" y2="${h-bottom}" stroke="var(--line)"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2"/><line x1="${x(state.radius)}" x2="${x(state.radius)}" y1="${top}" y2="${h-bottom}" stroke="var(--cyan)" stroke-dasharray="4 4"/>`+[.5,1,1.5,2,2.5].map(v=>`<text x="${x(v)}" y="${h-20}" fill="var(--muted)" font-size="12" text-anchor="middle">${v}</text>`).join('')+`<text x="${w/2}" y="${h-2}" fill="var(--muted)" font-size="12" text-anchor="middle">Radius · units</text><text x="${l}" y="12" fill="var(--muted)" font-size="11">Posterior probability · peak scaled to 1</text>`}
async function importCloud(e){
 const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){status('Choose a file smaller than 2 MB.');return}
 try{const text=await f.text();let points=[],pred=null,truth=null,provenance=null;if(f.name.toLowerCase().endsWith('.json')){let j=JSON.parse(text);points=Array.isArray(j)?j:j.points;pred=j.gnp||null;truth=j.truth||null;provenance=j.provenance||null;if(!Array.isArray(points))throw Error('JSON needs a points array.')}else{let obj=f.name.toLowerCase().endsWith('.obj');for(const line of text.split(/\r?\n/)){let s=line.trim();if(!s||s.startsWith('#'))continue;if(obj){if(!/^v\s/.test(s))continue;s=s.replace(/^v\s+/,'')}let p=s.split(/[\s,;]+/).slice(0,3).map(Number);if(p.length===3&&p.every(Number.isFinite))points.push(p);else if(!/^[xyzXYZ,;\s]+$/.test(s))throw Error('Each data row needs three finite coordinates.')}}
 if(points.length<30)throw Error('Provide at least 30 points.');if(!points.every(p=>Array.isArray(p)&&p.length===3&&p.every(v=>typeof v==='number'&&Number.isFinite(v)&&Math.abs(v)<1e8)))throw Error('Coordinates must be finite numbers with magnitude below 100 million.');for(const a of[pred,truth])if(a&&(!Array.isArray(a)||a.length!==points.length||!a.every(Number.isFinite)))throw Error('Curvature arrays must match the point count and contain finite numbers.');
 if(Math.max(...[0,1,2].map(a=>Math.max(...points.map(p=>p[a]))-Math.min(...points.map(p=>p[a]))))<1e-10)throw Error('The point cloud needs nonzero spatial extent.');const n=points.length,inds=Array.from({length:Math.min(n,2200)},(_,i)=>Math.floor(i*n/Math.min(n,2200)));storedImport={points:inds.map(i=>points[i]),gnp:pred?inds.map(i=>pred[i]):null,truth:truth?inds.map(i=>truth[i]):null,provenance,label:f.name};invalidate();state.shape='upload';controls();updateGeometry();status(`Loaded ${Math.min(n,2200).toLocaleString()} of ${n.toLocaleString()} points from ${f.name}.`);
 }catch(err){status('Could not import: '+err.message)}
}
function snapshot(){return {schema:'jr-geometry-experiment-v1',version:'1.0.0',created:new Date().toISOString(),state:{...state},points:dataset?.points,values,truth:dataset?.truth||null,baseline,provenance:state.tab==='models'?window.GNP_BENCHMARKS.provenance:state.shape==='upload'?storedImport?.provenance:null,method:$('method-badge').textContent,posterior:state.tab==='inverse'?posterior:null}}
function download(name,data,type='application/json'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function readNotes(){try{const n=JSON.parse(localStorage.getItem('jr-geometry-notebook-v1')||'[]');return Array.isArray(n)?n:[]}catch{return[]}}
function showNotebook(){const notes=readNotes();$('notebook-panel').innerHTML=`<p class="eyebrow">YOUR EXPERIMENTS / THIS DEVICE</p><h2>Keep the question with the result.</h2><p>Record predictions, compare outcomes, and choose the next experiment. Browser storage can be cleared; export important records.</p><div class="button-row"><button id="export-notebook">Export notebook</button></div><div id="notes-list"></div>`;if(!notes.length)$('notes-list').innerHTML='<div class="note-card"><h3>No experiments saved yet.</h3><p>Open an experiment, change a parameter, and select Save experiment.</p><button id="back-explore">Open surface explorer</button></div>';else $('notes-list').innerHTML=notes.map((n,i)=>`<article class="note-card"><p class="eyebrow">${escapeHtml(labels[n.state.tab]||n.state.tab)} / ${escapeHtml(new Date(n.created).toLocaleDateString())}</p><h3>${escapeHtml(n.name)}</h3><p>${escapeHtml(n.notes||'No observations recorded.')}</p><small>${escapeHtml(n.method)} · ${n.points?.length||0} points</small><div class="button-row"><button data-restore="${i}">Restore experiment</button><button data-export="${i}">Export JSON</button><button data-delete="${i}">Delete</button></div></article>`).join('');$('export-notebook').onclick=()=>download('geometry-notebook.json',JSON.stringify({schema:'jr-geometry-notebook-v1',experiments:notes},null,2));if($('back-explore'))$('back-explore').onclick=()=>switchTab('geometry');document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download('geometry-experiment.json',JSON.stringify(notes[+b.dataset.export],null,2)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this saved experiment from this device?'))return;notes.splice(+b.dataset.delete,1);try{localStorage.setItem('jr-geometry-notebook-v1',JSON.stringify(notes));showNotebook()}catch{status('Browser storage is unavailable.')}});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const n=notes[+b.dataset.restore];invalidate();Object.assign(state,n.state);if(state.shape==='upload')storedImport={points:n.points,truth:n.truth,gnp:n.method==='Imported GNP prediction'?n.values:null,provenance:n.provenance};baseline=n.baseline;switchTab(state.tab);status('Restored experiment settings and saved data. Camera position is reset separately.')})}
function showGuide(){
 $('learn-panel').innerHTML=`<p class="eyebrow">FIELD GUIDE / FROM INTUITION TO RESEARCH</p><h2>Seven experiments. One scientific habit.</h2><p>Predict a result, change one variable, measure the difference, and explain what you learned.</p><div class="guide-grid">
 <article class="guide-card"><p class="eyebrow">01 / GEOMETRY</p><h2>A surface has its own distances.</h2><p>An ant walks along a sphere, not straight through it. A metric tells us how to measure lengths and angles on the surface. Curvature describes how the surface bends. Gaussian curvature multiplies the two principal curvatures: positive on a sphere, negative on a saddle, and zero on the side of an ideal cylinder.</p><p class="formula">Sphere: K = 1/r²</p><p>Try sizes 0.6 and 1.2. The sphere doubles in radius, but its Gaussian curvature falls to one quarter.</p><button data-go="geometry">Explore curvature ↗</button></article>
 <article class="guide-card"><p class="eyebrow">02 / LEARNING</p><h2>An operator acts on a field.</h2><p>A field assigns a value to every location, like temperature across a surface. An operator transforms one field into another. A neural operator learns a transformation from examples while incorporating spatial relationships. These GNPs learn local surface representations that support geometric calculations.</p><p>Inspect predictions and errors separately. A visually smooth result is not evidence that a calculation is correct. Reference data and carefully chosen tests matter.</p><button data-go="models">Compare recorded predictions ↗</button></article>
 <article class="guide-card"><p class="eyebrow">03 / PHYSICS</p><h2>Geometry changes diffusion.</h2><p>The surface Laplacian describes local spreading along a surface. In the sphere experiment, the north–south concentration difference decays exponentially. A larger sphere has a longer distance over which to relax.</p><p class="formula">Timescale τ = r²/(2D)</p><p>Doubling radius multiplies this timescale by four. Doubling diffusivity divides it by two. This exact solution is a reference case for testing approximate solvers.</p><button data-go="diffusion">Run diffusion ↗</button></article>
 <article class="guide-card"><p class="eyebrow">04 / INFERENCE</p><h2>Observations constrain a shape.</h2><p>A forward model predicts measurements from a shape. An inverse model asks which shapes could explain measurements. Bayesian inference combines a prior and a likelihood into a posterior distribution.</p><p class="formula">Posterior ∝ likelihood × prior</p><p>Our sphere example assumes independent Gaussian noise and a bounded uniform radius prior. A narrow interval can still be wrong if the assumptions are wrong.</p><button data-go="inverse">Infer a radius ↗</button></article>
 <article class="guide-card"><p class="eyebrow">05 / TOPOLOGY</p><h2>Local curvature knows global topology.</h2><p>Gauss–Bonnet links a continuous geometric field to the discrete Euler characteristic.</p><p class="formula">∫M K dA = 2πχ(M)</p><p>A sphere integrates to 4π; a torus integrates to zero because positive and negative curvature cancel.</p><button data-go="topology">Test Gauss–Bonnet ↗</button></article>
 <article class="guide-card"><p class="eyebrow">06 / SPECTRAL GEOMETRY</p><h2>A shape has intrinsic frequencies.</h2><p>Laplace–Beltrami eigenfunctions form natural modes on a surface. On a sphere, degree ℓ has eigenvalue ℓ(ℓ+1)/r² and multiplicity 2ℓ+1.</p><p class="formula">ΔS Y = −λY</p><p>Changing radius changes the spectrum without changing topology.</p><button data-go="spectrum">Explore the spectrum ↗</button></article>
 <article class="guide-card"><p class="eyebrow">07 / GEOMETRIC FLOW</p><h2>Curvature can evolve the shape.</h2><p>Under mean-curvature flow a perfect sphere stays spherical while shrinking, providing an exact validation trajectory for numerical or learned solvers.</p><p class="formula">R(t)² = R₀² − 4t</p><button data-go="flow">Run curvature flow ↗</button></article>
 <article class="guide-card wide"><p class="eyebrow">CREDITS / COMPLETED CONTRIBUTIONS</p><h2>Website adaptation and enhancements by Joshua Randall.</h2><p>Joshua Randall developed the interactive website adaptation, responsive interface, live numerical experiments, model-comparison presentation, experiment notebook, import/export features, supporting Python workflow, and guided learning material.</p><p>The original GNP research, upstream software, and pretrained models are credited to Blaine Quackenbush and Paul J. Atzberger, with repository contributions credited upstream. The recorded neural predictions were generated using their models.</p><p>These additions extend the application and learning experience. Established mathematical methods retain their scientific attribution; no new GNP architecture or improvement to the pretrained models is claimed.</p><p><a href="CREDITS.md">Full credits and contribution record ↗</a></p></article>
 <article class="guide-card wide"><p class="eyebrow">RESEARCH / PRIMARY SOURCES</p><h2>Built around a reproducible comparison.</h2><ol><li><a href="https://doi.org/10.1007/s10462-024-11051-3" target="_blank" rel="noopener">Vijendran et al. (2025): AI for Geometry-Based Feature Extraction, Analysis and Synthesis in Artistic Images</a> · <a href="https://arxiv.org/abs/2412.01450" target="_blank" rel="noopener">Open manuscript</a>. Broad survey context for explicit geometric representations in extraction, analysis, and synthesis.</li><li><a href="https://doi.org/10.1088/2632-2153/ad8980" target="_blank" rel="noopener">Quackenbush & Atzberger (2024): Geometric Neural Operators</a> · <a href="https://arxiv.org/abs/2404.10843" target="_blank" rel="noopener">Open manuscript</a>. Geometric features, PDEs on manifolds, and shape inference.</li><li><a href="https://doi.org/10.1088/2632-2153/ae1bf8" target="_blank" rel="noopener">Transferable Foundation Models for Geometric Tasks (2025)</a> · <a href="https://arxiv.org/abs/2503.04649" target="_blank" rel="noopener">Open manuscript</a>. Reusable pretrained models and robustness experiments.</li><li><a href="https://arxiv.org/abs/2603.03621" target="_blank" rel="noopener">Extending Neural Operators (March 2026 preprint)</a>. Kernel extensions and derivative-aware approximation under stated mathematical conditions. This lab does not reproduce those extension results.</li><li><a href="https://github.com/atzberg/geo_neural_op" target="_blank" rel="noopener">geo_neural_op source and weights</a> · GPL-3.0. The benchmark export records the exact upstream revision and weight hashes.</li></ol><p>The artistic-image survey motivates the broader value of explicit geometric structure but is not implemented as an image-analysis model here. The browser baseline, analytic diffusion, Gauss–Bonnet quadrature, spherical spectral modes, exact mean-curvature flow, and Bayesian sphere calculation are separate educational implementations. They are not replicas of all methods in the papers. Imported scans require suitable sampling, units, and validation.</p><p><a href="METHODS.md">Read complete methods and limitations</a></p></article>
 <article class="guide-card wide"><p class="eyebrow">NEXT / A PERSONAL RESEARCH PROJECT</p><h2>How much noise is too much?</h2><p>Hold shape, point count, and seed fixed. Vary coordinate noise and neighborhood size. Save each result, compare mean absolute error, and repeat with several seeds. For a stronger study, vary sampling density and normal quality independently. Report failures as well as successes.</p><p>For new neural predictions, use the included research runner with the authors’ package, then import its JSON. Your uploaded data stays local unless you independently choose to send it elsewhere.</p></article></div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>switchTab(b.dataset.go))
}
function updatePointInspector(){
 const el=$('point-inspector');if(!el)return;
 if(selectedIndex==null||!dataset?.points?.[selectedIndex]){el.hidden=true;return}
 const i=selectedIndex,p=dataset.points[i],rows=[['Sample','#'+(i+1)],['x, y, z',p.map(v=>fmt(v,4)).join(', ')]];
 if(state.tab==='geometry'){
  if(Number.isFinite(dataset.truth?.[i]))rows.push(['Reference K',fmt(dataset.truth[i],5)]);
  if(baselineGeometry){
   rows.push(['Estimated K',fmt(baselineGeometry.gaussian[i],5)],['|H|',fmt(baselineGeometry.meanAbs[i],5)],['|κ|max / |κ|min',fmt(baselineGeometry.kMaxAbs[i],5)+' / '+fmt(baselineGeometry.kMinAbs[i],5)],['Fit RMS',fmt(baselineGeometry.residual[i],6)],['Neighborhood radius',fmt(baselineGeometry.radius[i],5)]);
  }
 }else if(state.tab==='models'){
  const b=window.GNP_BENCHMARKS?.cases?.[state.modelCase];if(b){rows.push(['Reference K',fmt(b.truth[i],5)],['GNP K',fmt(b.gnp[i],5)],['Local-fit K',fmt(b.baseline[i],5)],['GNP |error|',fmt(Math.abs(b.gnp[i]-b.truth[i]),5)])}
 }else if(state.tab==='topology'){
  if(Number.isFinite(gbDataset?.truth?.[i]))rows.push(['Reference K',fmt(gbDataset.truth[i],5)]);
  if(gbGeometry)rows.push(['Estimated K',fmt(gbGeometry.gaussian[i],5)],['Local |H|',fmt(gbGeometry.meanAbs[i],5)],['Fit RMS',fmt(gbGeometry.residual[i],6)]);
 }else if(state.tab==='spectrum'){
  rows.push(['Mode amplitude',fmt(values[i],5)],['Degree ℓ',String(state.spectrumL)]);
 }else if(state.tab==='flow'){
  rows.push(['Gaussian K',fmt(values[i],5)],['Flow time',fmt(state.flowTime,4)]);
 }else if(state.tab==='diffusion'){
  rows.push(['Concentration',fmt(values[i],5)],['Time',fmt(state.time,3)]);
 }
 el.innerHTML='<div class="inspector-head"><strong>Point inspector</strong><span>tap another sample to compare</span></div><div class="inspector-grid">'+rows.map(r=>'<div><span>'+escapeHtml(r[0])+'</span><strong>'+escapeHtml(r[1])+'</strong></div>').join('')+'</div>';
 el.hidden=false;
}
function switchTab(t){if(!['geometry','models','diffusion','topology','spectrum','flow','inverse','notebook','learn'].includes(t))t='geometry';if(worker){worker.terminate();worker=null;job++}playing=false;selectedIndex=null;state.tab=t;if(t==='diffusion')state.radius=Math.max(.5,Math.min(2,state.radius));if(t==='inverse')state.radius=Math.max(.6,Math.min(2.2,state.radius));document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===t)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const exp=!['notebook','learn'].includes(t);$('experiment').hidden=!exp;$('explanation').hidden=!exp;$('learn-panel').hidden=t!=='learn';$('notebook-panel').hidden=t!=='notebook';$('save-experiment').hidden=!exp;$('chart-wrap').hidden=t!=='inverse';if($('point-inspector'))$('point-inspector').hidden=true;status('');history.replaceState(null,'','#'+t);if(t==='learn')showGuide();else if(t==='notebook')showNotebook();else{controls();if(t==='geometry')updateGeometry();if(t==='models')updateModels();if(t==='diffusion')updateDiffusion();if(t==='topology')updateTopology();if(t==='spectrum')updateSpectrum();if(t==='flow')updateFlow();if(t==='inverse')updateInverse()}dirty=true}
// Canvas projection uses original coordinates and a view-only normalization.
const canvas=$('scene'),ctx=canvas.getContext('2d');let width=600,height=420;
